// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: attacker is a fuzzed address attempting to call setOwner;
    // newOwner is the address to set.
    function testFuzz_property(address attacker, address newOwner) public {
        // Keep domain wide but avoid zero-address for clarity (still admissible if fuzz hits it)
        vm.assume(attacker != address(0));

        // The reference contract sets admin = deployer (setUp() deployer == address(this) in tests),
        // and only that admin can call setOwner. We fuzz an arbitrary attacker trying to call setOwner.
        // In the correct contract, if attacker != admin, the call should revert / not succeed,
        // so owner remains the original deployer. We'll detect success by catching whether the call succeeded.

        bool ok;
        // make the call from the fuzzed attacker
        vm.prank(attacker);
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // The reference property: only the original deployer (the test contract which deployed c) can
        // change owner. Therefore, for ANY attacker address that is not the deployer/admin,
        // a call from that attacker must NOT succeed in changing owner. The original owner is the deployer
        // (address(this) at deployment time). We assert that either the call did not succeed (ok == false)
        // OR, if it claims success, the resulting owner is equal to the deployer (meaning attacker was admin).
        // This reads the public getter c.owner().
        address deployer = address(this);

        // Single assertion that must hold for the reference contract for ALL inputs, and which the mutant
        // (which treats owner as the admin) will violate for some inputs where attacker equals the current owner
        // (but is not the original deployer).
        assertTrue(!ok || c.owner() == deployer);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: caller (who will attempt to call setOwner) and newOwner (the address to set)
    function testFuzz_property(address caller, address newOwner) public {
        // Keep the domain wide: disallow the zero address as newOwner to avoid triviality
        // but still allow most addresses. Do not exclude the deployer (admin) — it's allowed.
        if (newOwner == address(0)) return;

        // The invariant we assert: when the deployer (admin) calls setOwner(newOwner), owner()==newOwner afterwards.
        // We will arrange the call as if made by the deployer (the address that deployed c in setUp()).
        // The deployer here is address(this) during setUp(), so admin == address(this) in the deployed contract.

        // Make the deployer call setOwner(newOwner)
        // ensure msg.sender is the deployer (this contract) for the call
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: the reference contract guarantees that the deployer (admin) can set owner to any nonzero address
        // and owner() will equal the provided newOwner after the call. The mutant (which checks msg.sender==owner) will break
        // this when owner was not previously equal to the deployer (which is true here because constructor set owner to deployer,
        // but the mutant only allows current owner to call; however we still assert the property on the reference which must hold).
        // We assert that the call succeeded and the stored owner equals newOwner.
        assertTrue(ok && c.owner() == newOwner);
    }
}
